You are a smart contract auditor, identify and explain severe vulnerabilities in the provided smart contract. Make sure that they are exploitable in real world and beneficial to attackers. Provide each identified vulnerability with intermediate reasoning and its associated function. Remember, you must provide the entire function code and do not use "...". Make your reasoning comprehensive and detailed. 
You should only output in below json format:
{
    "output_list": [
        {
            "function_name": "<function_name_1>",
            "code": "<original_function_code_1>",
            "vulnerability": "<short_vulnera_desc_1>",
            "reason": "<reason_1>"
        },
        {
            "function_name": "<function_name_2>",
            "code": "<original_function_code_2>",
            "vulnerability": "<short_vulnera_desc_2>",
            "reason": "<reason_2>"
        }
    ]
}
Output 3 most severe vulnerabilities.
If no vulnerability is detected, you should only output in this json format {"output_list": []}.
Smart contract code:

pragma solidity 0.8.3; interface iERC20 { function name() external view returns (string memory); function symbol() external view returns (string memory); function decimals() external view returns (uint); function totalSupply() external view returns (uint); function balanceOf(address account) external view returns (uint); function transfer(address, uint) external returns (bool); function allowance(address owner, address spender) external view returns (uint); function approve(address, uint) external returns (bool); function transferFrom(address, address, uint) external returns (bool); function transferTo(address, uint) external returns (bool); function burn(uint) external; function burnFrom(address, uint) external; event Transfer(address indexed from, address indexed to, uint value); event Approval(address indexed owner, address indexed spender, uint value); } interface iROUTER { function setParams(uint newFactor, uint newTime, uint newLimit) external; function addLiquidity(address base, uint inputBase, address token, uint inputToken) external returns(uint); function removeLiquidity(address base, address token, uint basisPoints) external returns (uint amountBase, uint amountToken); function swap(uint inputAmount, address inputToken, address outputToken) external returns (uint outputAmount); function swapWithLimit(uint inputAmount, address inputToken, address outputToken, uint slipLimit) external returns (uint outputAmount); function swapWithSynths(uint inputAmount, address inputToken, bool inSynth, address outputToken, bool outSynth) external returns (uint outputAmount); function swapWithSynthsWithLimit(uint inputAmount, address inputToken, bool inSynth, address outputToken, bool outSynth, uint slipLimit) external returns (uint outputAmount); function getILProtection(address member, address base, address token, uint basisPoints) external view returns(uint protection); function curatePool(address token) external; function listAnchor(address token) external; function replacePool(address oldToken, address newToken) external; function updateAnchorPrice(address token) external; function getAnchorPrice() external view returns (uint anchorPrice); function getVADERAmount(uint USDVAmount) external view returns (uint vaderAmount); function getUSDVAmount(uint vaderAmount) external view returns (uint USDVAmount); function isCurated(address token) external view returns(bool curated); function reserveUSDV() external view returns(uint); function reserveVADER() external view returns(uint); function getMemberBaseDeposit(address member, address token) external view returns(uint); function getMemberTokenDeposit(address member, address token) external view returns(uint); function getMemberLastDeposit(address member, address token) external view returns(uint); function getMemberCollateral(address member, address collateralAsset, address debtAsset) external view returns(uint); function getMemberDebt(address member, address collateralAsset, address debtAsset) external view returns(uint); function getSystemCollateral(address collateralAsset, address debtAsset) external view returns(uint); function getSystemDebt(address collateralAsset, address debtAsset) external view returns(uint); function getSystemInterestPaid(address collateralAsset, address debtAsset) external view returns(uint); } interface iUSDV { function ROUTER() external view returns (address); function isMature() external view returns (bool); function setParams(uint newDelay) external; function convert(uint amount) external returns(uint convertAmount); function convertForMember(address member, uint amount) external returns(uint convertAmount); function redeem(uint amount) external returns(uint redeemAmount); function redeemForMember(address member, uint amount) external returns(uint redeemAmount); } interface iVADER { function UTILS() external view returns (address); function DAO() external view returns (address); function emitting() external view returns (bool); function minting() external view returns (bool); function secondsPerEra() external view returns (uint); function flipEmissions() external; function flipMinting() external; function setParams(uint newEra, uint newCurve) external; function setRewardAddress(address newAddress) external; function changeUTILS(address newUTILS) external; function changeDAO(address newDAO) external; function purgeDAO() external; function upgrade(uint amount) external; function redeem() external returns (uint); function redeemToMember(address member) external returns (uint); } contract Attack { bool private inited; address public VADER; address public USDV; constructor() {} function init(address _vader, address _USDV) public { require(inited == false); inited = true; VADER = _vader; USDV = _USDV; } function attackUSDV(uint amount) public { iERC20(VADER).approve(USDV, amount); iERC20(USDV).approve(USDV, amount); iERC20(VADER).transferTo(address(this), amount); iUSDV(USDV).convert(amount); iUSDV(USDV).redeem(amount); } } interface iUTILS { function getFeeOnTransfer(uint totalSupply, uint maxSupply) external pure returns (uint); function assetChecks(address collateralAsset, address debtAsset) external; function isBase(address token) external view returns(bool base); function calcValueInBase(address token, uint amount) external view returns (uint); function calcValueInToken(address token, uint amount) external view returns (uint); function calcValueOfTokenInToken(address token1, uint amount, address token2) external view returns (uint); function calcSwapValueInBase(address token, uint amount) external view returns (uint); function calcSwapValueInToken(address token, uint amount) external view returns (uint); function requirePriceBounds(address token, uint bound, bool inside, uint targetPrice) external view; function getRewardShare(address token, uint rewardReductionFactor) external view returns (uint rewardShare); function getReducedShare(uint amount) external view returns(uint); function getProtection(address member, address token, uint basisPoints, uint timeForFullProtection) external view returns(uint protection); function getCoverage(address member, address token) external view returns (uint); function getCollateralValueInBase(address member, uint collateral, address collateralAsset, address debtAsset) external returns (uint debt, uint baseValue); function getDebtValueInCollateral(address member, uint debt, address collateralAsset, address debtAsset) external view returns(uint, uint); function getInterestOwed(address collateralAsset, address debtAsset, uint timeElapsed) external returns(uint interestOwed); function getInterestPayment(address collateralAsset, address debtAsset) external view returns(uint); function getDebtLoading(address collateralAsset, address debtAsset) external view returns(uint); function calcPart(uint bp, uint total) external pure returns (uint); function calcShare(uint part, uint total, uint amount) external pure returns (uint); function calcSwapOutput(uint x, uint X, uint Y) external pure returns (uint); function calcSwapFee(uint x, uint X, uint Y) external pure returns (uint); function calcSwapSlip(uint x, uint X) external pure returns (uint); function calcLiquidityUnits(uint b, uint B, uint t, uint T, uint P) external view returns (uint); function getSlipAdustment(uint b, uint B, uint t, uint T) external view returns (uint); function calcSynthUnits(uint b, uint B, uint P) external view returns (uint); function calcAsymmetricShare(uint u, uint U, uint A) external pure returns (uint); function calcCoverage(uint B0, uint T0, uint B1, uint T1) external pure returns(uint); function sortArray(uint[] memory array) external pure returns (uint[] memory); } interface iVAULT { function setParams(uint newEra, uint newDepositTime, uint newGrantTime) external; function grant(address recipient, uint amount) external; function deposit(address synth, uint amount) external; function depositForMember(address synth, address member, uint amount) external; function harvest(address synth) external returns(uint reward); function calcCurrentReward(address synth, address member) external view returns(uint reward); function calcReward(address synth, address member) external view returns(uint); function withdraw(address synth, uint basisPoints) external returns(uint redeemedAmount); function totalWeight() external view returns(uint); function reserveUSDV() external view returns(uint); function reserveVADER() external view returns(uint); function getMemberDeposit(address synth, address member) external view returns(uint); function getMemberWeight(address member) external view returns(uint); function getMemberLastTime(address synth, address member) external view returns(uint); } contract DAO { struct GrantDetails{ address recipient; uint amount; } bool private inited; uint public proposalCount; address public VADER; address public USDV; address public VAULT; uint public coolOffPeriod; mapping(uint => GrantDetails) public mapPID_grant; mapping(uint => address) public mapPID_address; mapping(uint => string) public mapPID_type; mapping(uint => uint) public mapPID_votes; mapping(uint => uint) public mapPID_timeStart; mapping(uint => bool) public mapPID_finalising; mapping(uint => bool) public mapPID_finalised; mapping(uint => mapping(address => uint)) public mapPIDMember_votes; event NewProposal(address indexed member, uint indexed proposalID, string proposalType); event NewVote(address indexed member, uint indexed proposalID, uint voteWeight, uint totalVotes, string proposalType); event ProposalFinalising(address indexed member,uint indexed proposalID, uint timeFinalised, string proposalType); event CancelProposal(address indexed member, uint indexed oldProposalID, uint oldVotes, uint newVotes, uint totalWeight); event FinalisedProposal(address indexed member,uint indexed proposalID, uint votesCast, uint totalWeight, string proposalType); constructor() { } function init(address _vader, address _usdv, address _vault) public { require(inited == false); inited = true; VADER = _vader; USDV = _usdv; VAULT = _vault; coolOffPeriod = 1; } function newGrantProposal(address recipient, uint amount) public { string memory typeStr = "GRANT"; proposalCount += 1; mapPID_type[proposalCount] = typeStr; GrantDetails memory grant; grant.recipient = recipient; grant.amount = amount; mapPID_grant[proposalCount] = grant; emit NewProposal(msg.sender, proposalCount, typeStr); } function newAddressProposal(address proposedAddress, string memory typeStr) public { proposalCount += 1; mapPID_address[proposalCount] = proposedAddress; mapPID_type[proposalCount] = typeStr; emit NewProposal(msg.sender, proposalCount, typeStr); } function voteProposal(uint proposalID) public returns (uint voteWeight) { bytes memory _type = bytes(mapPID_type[proposalID]); voteWeight = countMemberVotes(proposalID); if(hasQuorum(proposalID) && mapPID_finalising[proposalID] == false){ if(isEqual(_type, 'DAO') || isEqual(_type, 'UTILS') || isEqual(_type, 'REWARD')){ if(hasMajority(proposalID)){ _finalise(proposalID); } } else { _finalise(proposalID); } } emit NewVote(msg.sender, proposalID, voteWeight, mapPID_votes[proposalID], string(_type)); } function _finalise(uint _proposalID) internal { bytes memory _type = bytes(mapPID_type[_proposalID]); mapPID_finalising[_proposalID] = true; mapPID_timeStart[_proposalID] = block.timestamp; emit ProposalFinalising(msg.sender, _proposalID, block.timestamp+coolOffPeriod, string(_type)); } function cancelProposal(uint oldProposalID, uint newProposalID) public { require(mapPID_finalising[oldProposalID], "Must be finalising"); require(hasMinority(newProposalID), "Must have minority"); require(isEqual(bytes(mapPID_type[oldProposalID]), bytes(mapPID_type[newProposalID])), "Must be same"); mapPID_votes[oldProposalID] = 0; emit CancelProposal(msg.sender, oldProposalID, mapPID_votes[oldProposalID], mapPID_votes[newProposalID], iVAULT(VAULT).totalWeight()); } function finaliseProposal(uint proposalID) public { require((block.timestamp - mapPID_timeStart[proposalID]) > coolOffPeriod, "Must be after cool off"); require(mapPID_finalising[proposalID] == true, "Must be finalising"); if(!hasQuorum(proposalID)){ _finalise(proposalID); } bytes memory _type = bytes(mapPID_type[proposalID]); if (isEqual(_type, 'GRANT')){ grantFunds(proposalID); } else if (isEqual(_type, 'UTILS')){ moveUtils(proposalID); } else if (isEqual(_type, 'REWARD')){ moveRewardAddress(proposalID); } } function completeProposal(uint _proposalID) internal { string memory _typeStr = mapPID_type[_proposalID]; emit FinalisedProposal(msg.sender, _proposalID, mapPID_votes[_proposalID], iVAULT(VAULT).totalWeight(), _typeStr); mapPID_votes[_proposalID] = 0; mapPID_finalised[_proposalID] = true; mapPID_finalising[_proposalID] = false; } function grantFunds(uint _proposalID) internal { GrantDetails memory _grant = mapPID_grant[_proposalID]; require(_grant.amount <= iERC20(USDV).balanceOf(VAULT) / 10, "Not more than 10%"); completeProposal(_proposalID); iVAULT(VAULT).grant(_grant.recipient, _grant.amount); } function moveUtils(uint _proposalID) internal { address _proposedAddress = mapPID_address[_proposalID]; require(_proposedAddress != address(0), "No address proposed"); iVADER(VADER).changeUTILS(_proposedAddress); completeProposal(_proposalID); } function moveRewardAddress(uint _proposalID) internal { address _proposedAddress = mapPID_address[_proposalID]; require(_proposedAddress != address(0), "No address proposed"); iVADER(VADER).setRewardAddress(_proposedAddress); completeProposal(_proposalID); } function countMemberVotes(uint _proposalID) internal returns (uint voteWeight){ mapPID_votes[_proposalID] -= mapPIDMember_votes[_proposalID][msg.sender]; voteWeight = iVAULT(VAULT).getMemberWeight(msg.sender); mapPID_votes[_proposalID] += voteWeight; mapPIDMember_votes[_proposalID][msg.sender] = voteWeight; } function hasMajority(uint _proposalID) public view returns(bool){ uint votes = mapPID_votes[_proposalID]; uint consensus = iVAULT(VAULT).totalWeight() / 2; if(votes > consensus){ return true; } else { return false; } } function hasQuorum(uint _proposalID) public view returns(bool){ uint votes = mapPID_votes[_proposalID]; uint consensus = iVAULT(VAULT).totalWeight() / 3; if(votes > consensus){ return true; } else { return false; } } function hasMinority(uint _proposalID) public view returns(bool){ uint votes = mapPID_votes[_proposalID]; uint consensus = iVAULT(VAULT).totalWeight() / 6; if(votes > consensus){ return true; } else { return false; } } function isEqual(bytes memory part1, bytes memory part2) public pure returns(bool){ if(sha256(part1) == sha256(part2)){ return true; } else { return false; } } } contract Synth is iERC20 { address public FACTORY; address public TOKEN; string public override name; string public override symbol; uint public override decimals = 18; uint public override totalSupply; mapping(address => uint) private _balances; mapping(address => mapping(address => uint)) private _allowances; modifier onlyFACTORY() { require(msg.sender == FACTORY, "!FACTORY"); _; } constructor(address _token){ TOKEN = _token; FACTORY = msg.sender; string memory synthName = " - vSynth"; string memory synthSymbol = ".v"; name = string(abi.encodePacked(iERC20(_token).name(), synthName)); symbol = string(abi.encodePacked(iERC20(_token).symbol(), synthSymbol)); } function balanceOf(address account) public view override returns (uint) { return _balances[account]; } function allowance(address owner, address spender) public view virtual override returns (uint) { return _allowances[owner][spender]; } function transfer(address recipient, uint amount) public virtual override returns (bool) { _transfer(msg.sender, recipient, amount); return true; } function approve(address spender, uint amount) public virtual override returns (bool) { _approve(msg.sender, spender, amount); return true; } function _approve(address owner, address spender, uint amount) internal virtual { require(owner != address(0), "sender"); require(spender != address(0), "spender"); _allowances[owner][spender] = amount; emit Approval(owner, spender, amount); } function transferFrom(address sender, address recipient, uint amount) public virtual override returns (bool) { _transfer(sender, recipient, amount); _approve(sender, msg.sender, _allowances[sender][msg.sender] - amount); return true; } function transferTo(address recipient, uint amount) public virtual override returns (bool) { _transfer(tx.origin, recipient, amount); return true; } function _transfer(address sender, address recipient, uint amount) internal virtual { require(sender != address(0), "sender"); require(recipient != address(this), "recipient"); _balances[sender] -= amount; _balances[recipient] += amount; emit Transfer(sender, recipient, amount); } function mint(address account, uint amount) external virtual onlyFACTORY { require(account != address(0), "recipient"); totalSupply += amount; _balances[account] += amount; emit Transfer(address(0), account, amount); } function burn(uint amount) public virtual override { _burn(msg.sender, amount); } function burnFrom(address account, uint amount) public virtual override { uint decreasedAllowance = allowance(account, msg.sender) - amount; _approve(account, msg.sender, decreasedAllowance); _burn(account, amount); } function _burn(address account, uint amount) internal virtual { require(account != address(0), "address err"); _balances[account] -= amount; totalSupply -= amount; emit Transfer(account, address(0), amount); } } contract Factory { bool private inited; address public VADER; address public USDV; address public POOLS; address[] public arraySynths; mapping(address => address) public getSynth; mapping(address => bool) public isSynth; event CreateSynth(address indexed token, address indexed pool); modifier onlyPOOLS() { require(msg.sender == POOLS, "!POOLS"); _; } constructor(){ } function init(address _pool) public { require(inited == false); inited = true; POOLS = _pool; } function deploySynth(address token) external onlyPOOLS returns(address synth) { require(getSynth[token] == address(0), "CreateErr"); Synth newSynth; newSynth = new Synth(token); synth = address(newSynth); _addSynth(token, synth); emit CreateSynth(token, synth); } function mintSynth(address synth, address member, uint amount) external onlyPOOLS returns(bool) { Synth(synth).mint(member, amount); return true; } function _addSynth(address _token, address _synth) internal { getSynth[_token] = _synth; arraySynths.push(_synth); isSynth[_synth] = true; } } interface iFACTORY{ function deploySynth(address) external returns(address); function mintSynth(address, address, uint) external returns(bool); function getSynth(address) external view returns (address); function isSynth(address) external view returns (bool); } contract Pools { bool private inited; uint public pooledVADER; uint public pooledUSDV; address public VADER; address public USDV; address public ROUTER; address public FACTORY; mapping(address => bool) _isMember; mapping(address => bool) _isAsset; mapping(address => bool) _isAnchor; mapping(address => uint) public mapToken_Units; mapping(address => mapping(address => uint)) public mapTokenMember_Units; mapping(address => uint) public mapToken_baseAmount; mapping(address => uint) public mapToken_tokenAmount; event AddLiquidity(address indexed member, address indexed base, uint baseAmount, address indexed token, uint tokenAmount, uint liquidityUnits); event RemoveLiquidity(address indexed member, address indexed base, uint baseAmount, address indexed token, uint tokenAmount, uint liquidityUnits, uint totalUnits); event Swap(address indexed member, address indexed inputToken, uint inputAmount, address indexed outputToken, uint outputAmount, uint swapFee); event Sync(address indexed token, address indexed pool, uint addedAmount); event SynthSync(address indexed token, uint burntSynth, uint deletedUnits); constructor() {} function init(address _vader, address _usdv, address _router, address _factory) public { require(inited == false); inited = true; VADER = _vader; USDV = _usdv; ROUTER = _router; FACTORY = _factory; } function addLiquidity(address base, address token, address member) external returns(uint liquidityUnits) { require(token != USDV && token != VADER); uint _actualInputBase; if(base == VADER){ if(!isAnchor(token)){ _isAnchor[token] = true; } _actualInputBase = getAddedAmount(VADER, token); } else if (base == USDV) { if(!isAsset(token)){ _isAsset[token] = true; } _actualInputBase = getAddedAmount(USDV, token); } uint _actualInputToken = getAddedAmount(token, token); liquidityUnits = iUTILS(UTILS()).calcLiquidityUnits(_actualInputBase, mapToken_baseAmount[token], _actualInputToken, mapToken_tokenAmount[token], mapToken_Units[token]); mapTokenMember_Units[token][member] += liquidityUnits; mapToken_Units[token] += liquidityUnits; mapToken_baseAmount[token] += _actualInputBase; mapToken_tokenAmount[token] += _actualInputToken; emit AddLiquidity(member, base, _actualInputBase, token, _actualInputToken, liquidityUnits); } function removeLiquidity(address base, address token, uint basisPoints) external returns (uint outputBase, uint outputToken) { return _removeLiquidity(base, token, basisPoints, tx.origin); } function removeLiquidityDirectly(address base, address token, uint basisPoints) external returns (uint outputBase, uint outputToken) { return _removeLiquidity(base, token, basisPoints, msg.sender); } function _removeLiquidity(address base, address token, uint basisPoints, address member) internal returns (uint outputBase, uint outputToken) { require(base == USDV || base == VADER); uint _units = iUTILS(UTILS()).calcPart(basisPoints, mapTokenMember_Units[token][member]); outputBase = iUTILS(UTILS()).calcShare(_units, mapToken_Units[token], mapToken_baseAmount[token]); outputToken = iUTILS(UTILS()).calcShare(_units, mapToken_Units[token], mapToken_tokenAmount[token]); mapToken_Units[token] -=_units; mapTokenMember_Units[token][member] -= _units; mapToken_baseAmount[token] -= outputBase; mapToken_tokenAmount[token] -= outputToken; emit RemoveLiquidity(member, base, outputBase, token, outputToken, _units, mapToken_Units[token]); transferOut(base, outputBase, member); transferOut(token, outputToken, member); return (outputBase, outputToken); } function swap(address base, address token, address member, bool toBase) external returns (uint outputAmount) { if(toBase){ uint _actualInput = getAddedAmount(token, token); outputAmount = iUTILS(UTILS()).calcSwapOutput(_actualInput, mapToken_tokenAmount[token], mapToken_baseAmount[token]); uint _swapFee = iUTILS(UTILS()).calcSwapFee(_actualInput, mapToken_tokenAmount[token], mapToken_baseAmount[token]); mapToken_tokenAmount[token] += _actualInput; mapToken_baseAmount[token] -= outputAmount; emit Swap(member, token, _actualInput, base, outputAmount, _swapFee); transferOut(base, outputAmount, member); } else { uint _actualInput = getAddedAmount(base, token); outputAmount = iUTILS(UTILS()).calcSwapOutput(_actualInput, mapToken_baseAmount[token], mapToken_tokenAmount[token]); uint _swapFee = iUTILS(UTILS()).calcSwapFee(_actualInput, mapToken_baseAmount[token], mapToken_tokenAmount[token]); mapToken_baseAmount[token] += _actualInput; mapToken_tokenAmount[token] -= outputAmount; emit Swap(member, base, _actualInput, token, outputAmount, _swapFee); transferOut(token, outputAmount, member); } } function sync(address token, address pool) external { uint _actualInput = getAddedAmount(token, pool); if (token == VADER || token == USDV){ mapToken_baseAmount[pool] += _actualInput; } else { mapToken_tokenAmount[pool] += _actualInput; } emit Sync(token, pool, _actualInput); } function deploySynth(address token) external { require(token != VADER || token != USDV); iFACTORY(FACTORY).deploySynth(token); } function mintSynth(address base, address token, address member) external returns (uint outputAmount) { require(iFACTORY(FACTORY).isSynth(getSynth(token)), "!synth"); uint _actualInputBase = getAddedAmount(base, token); uint _synthUnits = iUTILS(UTILS()).calcSynthUnits(_actualInputBase, mapToken_baseAmount[token], mapToken_Units[token]); outputAmount = iUTILS(UTILS()).calcSwapOutput(_actualInputBase, mapToken_baseAmount[token], mapToken_tokenAmount[token]); mapTokenMember_Units[token][address(this)] += _synthUnits; mapToken_Units[token] += _synthUnits; mapToken_baseAmount[token] += _actualInputBase; emit AddLiquidity(member, base, _actualInputBase, token, 0, _synthUnits); iFACTORY(FACTORY).mintSynth(getSynth(token), member, outputAmount); } function burnSynth(address base, address token, address member) external returns (uint outputBase) { uint _actualInputSynth = iERC20(getSynth(token)).balanceOf(address(this)); uint _unitsToDelete = iUTILS(UTILS()).calcShare(_actualInputSynth, iERC20(getSynth(token)).totalSupply(), mapTokenMember_Units[token][address(this)]); iERC20(getSynth(token)).burn(_actualInputSynth); mapTokenMember_Units[token][address(this)] -= _unitsToDelete; mapToken_Units[token] -= _unitsToDelete; outputBase = iUTILS(UTILS()).calcSwapOutput(_actualInputSynth, mapToken_tokenAmount[token], mapToken_baseAmount[token]); mapToken_baseAmount[token] -= outputBase; emit RemoveLiquidity(member, base, outputBase, token, 0, _unitsToDelete, mapToken_Units[token]); transferOut(base, outputBase, member); } function syncSynth(address token) external { uint _actualInputSynth = iERC20(getSynth(token)).balanceOf(address(this)); uint _unitsToDelete = iUTILS(UTILS()).calcShare(_actualInputSynth, iERC20(getSynth(token)).totalSupply(), mapTokenMember_Units[token][address(this)]); iERC20(getSynth(token)).burn(_actualInputSynth); mapTokenMember_Units[token][address(this)] -= _unitsToDelete; mapToken_Units[token] -= _unitsToDelete; emit SynthSync(token, _actualInputSynth, _unitsToDelete); } function lockUnits(uint units, address token, address member) external { mapTokenMember_Units[token][member] -= units; mapTokenMember_Units[token][msg.sender] += 